input.sparql:
PREFIX brick: <http://brickschema.org/schema/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?label WHERE {
  ?z rdfs:label ?label .
  FILTER (CONTAINS(LCASE(?label), "perimeter") || CONTAINS(LCASE(?label), "ZN"))
}

PREFIX brick: <http://brickschema.org/schema/Brick#>
PREFIX ref: <http://w3.org/ns/ldes#>
SELECT ?point ?cls ?ts WHERE {
  ?point brick:hasLocation <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z02> .
  OPTIONAL { ?point a ?cls . }
  OPTIONAL { ?point ref:hasTimeseriesId ?ts . }
}

PREFIX brick: <http://brickschema.org/schema/Brick#>
SELECT ?z (?p (COUNT(?s) as ?c)) WHERE {
  ?s ?p <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z02> .
  GROUP BY ?p
}
